import argparse
import json

ITEMS = [
    {"name": "write report", "priority": 2},
    {"name": "backup db", "priority": 1},
    {"name": "call vendor", "priority": 3},
    {"name": "archive logs", "priority": 2},
]


def _positive_int(value):
    try:
        n = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid int value: {value!r}")
    if n <= 0:
        raise argparse.ArgumentTypeError(f"must be a positive integer, got {n}")
    return n


def main(argv=None):
    p = argparse.ArgumentParser(prog="tasks")
    p.add_argument("--json", action="store_true", help="print as JSON")
    p.add_argument("--limit", type=_positive_int, help="print only the first N items")
    p.add_argument("--sort", choices=("name", "priority"), help="sort items by name or priority")
    args = p.parse_args(argv)
    items = list(ITEMS)
    if args.sort == "name":
        items.sort(key=lambda it: it["name"])
    elif args.sort == "priority":
        items.sort(key=lambda it: (it["priority"], it["name"]))
    if args.limit is not None:
        items = items[: args.limit]
    if args.json:
        print(json.dumps({"items": items}))
    else:
        for it in items:
            print(f"{it['priority']} {it['name']}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

